def _post_message(token, chat_id, text, keyboard=None):
    params = {
        'chat_id': chat_id,
        'text': text,
        'disable_web_page_preview': 'true',
    }
    if keyboard:
        params['reply_markup'] = json.dumps(keyboard)

    parsed = _call(token, 'sendMessage', params)
    if parsed.get('ok'):
        return True, ''
    return False, _explain(parsed.get('description'))


def send(app, text, event=None, event_key=None, cooldown=DEFAULT_COOLDOWN_SECONDS):
    """Queue a notification. Returns immediately; never raises.

    `event` is one of EVENT_TYPES and decides whether this category is enabled;
    `event_key` de-duplicates repeats of the same specific occurrence.
    """
    if not app or not text:
        return

    if event_key:
        now_ts = time.monotonic()
        with _last_sent_lock:
            previous = _last_sent.get(event_key)
            if previous is not None and now_ts - previous < cooldown:
                return
            _last_sent[event_key] = now_ts

    def _worker():
        try:
            settings = load_settings(app)
            if not settings['enabled'] or not settings['token'] or not settings['chat_id']:
                return
            if event and not settings['events'].get(event, True):
                return
            ok, error_text = _post_message(settings['token'], settings['chat_id'], translate_bot(text, settings.get('language', 'en')))
            if not ok:
                logger.warning(f'Telegram notification rejected: {error_text}')
        except Exception as send_error:
            logger.warning(f'Telegram notification failed: {send_error}')

    threading.Thread(target=_worker, daemon=True, name='notify').start()


def send_test(app, text='GNSS Caster: test notification'):
    """Synchronous send used by the "Send test message" button."""
    settings = load_settings(app)
    if not settings['token'] or not settings['chat_id']:
        return False, translate_bot('Bot token and chat ID are both required', settings.get('language', 'en'))
    if not settings['enabled']:
        return False, translate_bot('Notifications are disabled', settings.get('language', 'en'))
    try:
        return _post_message(settings['token'], settings['chat_id'], translate_bot(text, settings.get('language', 'en')))
    except Exception as send_error:
        return False, str(send_error)


