    "3.2": "RTCM Standard 10403.2",
    "3.3": "RTCM Standard 10403.3",
    "3.1": "RTCM Standard 10403.1"
}

# Receiver-managed RTCM messages that can be safely generated from the
# global RTCM Settings page for the default base-station workflow.
RECEIVER_STARTUP_MESSAGE_ORDER = [1006, 1033, 1075, 1085, 1095, 1125, 1230]
RECEIVER_STARTUP_MESSAGE_RULES = {
    1006: {'interval': 5, 'default_enabled': True},
    1033: {'interval': 10, 'default_enabled': True},
    1075: {'interval': 'output_interval', 'default_enabled': True},
    1085: {'interval': 'output_interval', 'default_enabled': True},
    1095: {'interval': 'output_interval', 'default_enabled': True},
    1125: {'interval': 'output_interval', 'default_enabled': True},
    1230: {'interval': 'output_interval', 'default_enabled': True},
}

def get_message_description(msg_type):
    """Get description for RTCM message type"""
    return RTCM_DESCRIPTIONS.get(msg_type, f"RTCM Message Type {msg_type}")

def is_message_supported(msg_type):
    """Check if message type is in registry"""
    for group in RTCM_GROUPS.values():
        if msg_type in group:
            return True
    return False

def get_message_group(msg_type):
    """Get group name for message type"""
    for group_name, messages in RTCM_GROUPS.items():
        if msg_type in messages:
            return group_name
    return "Unknown"

def get_all_messages_by_group(group_name=None):
    """Get all messages, optionally filtered by group"""
    if group_name:
        return RTCM_GROUPS.get(group_name, [])
    
    all_messages = []
    for messages in RTCM_GROUPS.values():
        all_messages.extend(messages)
    return sorted(list(set(all_messages)))

def get_groups():
    """Get all available groups"""
    return list(RTCM_GROUPS.keys())

def get_receiver_startup_message_types():
    """Get RTCM message types managed by default receiver startup generation."""
    return list(RECEIVER_STARTUP_MESSAGE_ORDER)

def get_default_enabled_rtcm_message_types():
    """Get RTCM message types enabled by default in a fresh install/reset."""
    return [
        msg_type for msg_type in RECEIVER_STARTUP_MESSAGE_ORDER
        if RECEIVER_STARTUP_MESSAGE_RULES.get(msg_type, {}).get('default_enabled', False)
    ]

def is_default_rtcm_enabled(msg_type):
    """Check whether a message should be enabled by default."""
    try:
        normalized_type = int(msg_type)
    except (TypeError, ValueError):
        return False
    return normalized_type in set(get_default_enabled_rtcm_message_types())

def build_receiver_rtcm_commands(enabled_message_types=None, output_interval=1):
    """Build default receiver commands from the current RTCM message set."""
    try:
        normalized_interval = max(1, int(output_interval))
    except (TypeError, ValueError):
        normalized_interval = 1

    if enabled_message_types is None:
        enabled_types = set(get_default_enabled_rtcm_message_types())
    else:
        enabled_types = set()
        for raw_type in enabled_message_types:
            try:
                enabled_types.add(int(raw_type))
            except (TypeError, ValueError):
                continue

    commands = []
    for msg_type in RECEIVER_STARTUP_MESSAGE_ORDER:
        if msg_type not in enabled_types:
            continue

        rule = RECEIVER_STARTUP_MESSAGE_RULES.get(msg_type, {})
        interval_rule = rule.get('interval', 'output_interval')
        if interval_rule == 'output_interval':
            interval_value = normalized_interval
        else:
            try:
                interval_value = max(1, int(interval_rule))
            except (TypeError, ValueError):
                interval_value = normalized_interval

        commands.append(f'rtcm{msg_type} {interval_value}')

    return commands

def export_settings(settings):
    """Export RTCM settings as JSON"""
    return json.dumps(settings, indent=2)

def import_settings(json_str):
    """Import RTCM settings from JSON"""
    try:
        return json.loads(json_str)
    except Exception:
        return {}
