        @app.route('/api/base_stations/<int:id>/config_versions/<int:version_id>')
        @login_required
        def api_base_station_config_version_detail(id, version_id):
            """Return a single config version's full snapshot, plus a diff against
            the station's current config so the UI can highlight changes."""
            try:
                station = BaseStation.query.get_or_404(id)
                version = ReceiverConfigVersion.query.filter_by(
                    id=version_id, station_id=station.id
                ).first()
                if not version:
                    return jsonify({'error': 'Config version not found'}), 404

                try:
                    snapshot = json.loads(version.config_json or '{}')
                except Exception:
                    snapshot = {}

                current = _snapshot_station_config(station)
                diff = {}
                for field in _CONFIG_FIELDS:
                    old_val = snapshot.get(field)
                    cur_val = current.get(field)
                    if str(old_val) != str(cur_val):
                        diff[field] = {'version': old_val, 'current': cur_val}

                return jsonify({
                    'id': version.id,
                    'version': version.version,
                    'source': version.source,
                    'note': version.note,
                    'created_by': version.created_by,
                    'created_at': version.created_at,
                    'config': snapshot,
                    'diff_vs_current': diff,
                })
            except Exception as e:
                logger.error(f"Error fetching config version detail: {e}")
                return jsonify({'error': str(e)}), 500

        @app.route('/api/base_stations/<int:id>/config_versions/<int:version_id>/restore', methods=['POST'])
        @login_required
        def api_base_station_config_version_restore(id, version_id):
            """Restore a station's config-bearing fields from a saved version.

            This does NOT re-apply to the receiver automatically; it only updates
            the stored config. The operator can then hit "Apply Config" to push
            it. A new 'restore' version is recorded for the audit trail.
            """
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                station = BaseStation.query.get_or_404(id)
                version = ReceiverConfigVersion.query.filter_by(
                    id=version_id, station_id=station.id
                ).first()
                if not version:
                    return jsonify({'error': 'Config version not found'}), 404

                try:
                    snapshot = json.loads(version.config_json or '{}')
                except Exception:
                    return jsonify({'error': 'Stored config is corrupt'}), 500

                for field in _CONFIG_FIELDS:
                    if field in snapshot:
                        setattr(station, field, snapshot[field])
                station.updated_at = int(time.time())
                db.session.commit()

                _record_config_version(
                    station, source='restore',
                    note=f'Restored from version {version.version}', force=True
                )
                db.session.commit()

                return jsonify({
                    'message': f'Configuration restored from version {version.version}',
                    'restored_from': version.version,
                }), 200
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error restoring config version: {e}")
                return jsonify({'error': str(e)}), 500
        
