        @app.route('/api/system/updates/install', methods=['POST'])
        @login_required
        def api_release_update_install():
            denied = _require_admin_role()
            if denied:
                return denied
            data = request.get_json(silent=True)
            if not isinstance(data, dict) or data.get('confirm') != 'UPDATE':
                return jsonify({'error': 'Type UPDATE to confirm'}), 400
            tag, digest = str(data.get('tag') or ''), str(data.get('sha256') or '')
            if not re.fullmatch(r'v[0-9]{1,4}\.[0-9]{1,4}\.[0-9]{1,4}', tag) or not re.fullmatch(r'[0-9a-f]{64}', digest):
                return jsonify({'error': 'Invalid release selection'}), 400
            client_ip = _get_client_ip()
            if _get_login_ip_block_seconds(client_ip):
                return jsonify({'error': 'Too many password attempts. Try again later.'}), 429
            password = str(data.get('password') or '')
            if not password or not bcrypt.check_password_hash(current_user.password, password):
                _record_login_ip_failure(client_ip)
                return jsonify({'error': 'Current password is incorrect'}), 403
            # Database counters are checked again by the root worker immediately
            # before installation. Root also verifies the selected release.
            if any(int(rover.active_conn or 0) > 0 for rover in Rover.query.all()):
                return jsonify({'error': 'Disconnect all rovers before updating'}), 409
            return _release_update_response('release-install', (tag, digest), timeout=40, status_code=202)

