        @app.route('/api/system/backups/storage')
        @login_required
        def api_system_backup_storage():
            """Where backups actually land, and whether that will survive.

            The dangerous failure mode is a backup nobody checks: it lives on
            the same card as the system, or the USB drive silently unmounted
            after a reboot. This reports both, plus free space.
            """
            import shutil

            def describe(path_value, label):
                entry = {
                    'label': label,
                    'path': path_value,
                    'configured': bool(path_value),
                    'exists': False,
                    'writable': False,
                    'device': '',
                    'free_bytes': 0,
                    'total_bytes': 0,
                }
                if not path_value:
                    return entry
                entry['exists'] = os.path.isdir(path_value)
                if not entry['exists']:
                    return entry
                entry['writable'] = os.access(path_value, os.W_OK)
                try:
                    usage = shutil.disk_usage(path_value)
                    entry['free_bytes'] = int(usage.free)
                    entry['total_bytes'] = int(usage.total)
                except OSError:
                    pass
                try:
                    entry['device'] = str(os.stat(path_value).st_dev)
                except OSError:
                    pass
                return entry

            try:
                # Same directory _list_backup_files() reads, so both agree.
                local_path = '/opt/gnss-caster/backups'
                external_path = str(
                    _get_system_setting_value('backup_external_path', '') or ''
                ).strip()

                local = describe(local_path, 'Primary (on this host)')
                external = describe(external_path, 'Second copy')

                warnings = []
                if not external['configured']:
                    warnings.append(
                        'No second copy configured: a card failure would take the backups with it.'
                    )
                elif not external['exists']:
                    warnings.append(
                        f'Second copy path "{external_path}" does not exist - is the drive mounted?'
                    )
                elif not external['writable']:
                    warnings.append(f'Second copy path "{external_path}" is not writable.')
                elif external['device'] and external['device'] == local['device']:
                    warnings.append(
                        'Second copy is on the same filesystem as the primary, '
                        'so it will not survive a card failure.'
                    )

                return jsonify({
                    'local': local,
                    'external': external,
                    'warnings': warnings,
                })
            except Exception as e:
                logger.error(f'Error getting backup storage information: {e}')
                return jsonify({'error': str(e)}), 500

        @app.route('/api/system/backups/verify', methods=['POST'])
        @login_required
        def api_system_backup_verify():
            """Check that an archive is actually readable, on demand."""
            try:
                data = request.get_json(silent=True) or {}
                try:
                    # Returns (safe_name, path) and raises if the name is unsafe
                    # or the file is missing - unpack it, do not use it directly.
                    _safe_name, archive_path = _resolve_backup_archive_path(
                        str(data.get('filename', ''))
                    )
                except ValueError as name_error:
                    # A bad or unsafe filename is a client mistake, not a
                    # server fault - report it as such.
                    return jsonify({'error': str(name_error)}), 400
                except FileNotFoundError:
                    return jsonify({'error': 'Backup not found'}), 404

                verify_path = archive_path
                temp_plain_path = ''
                try:
                    if archive_path.endswith('.enc'):
                        passphrase = str(
                            data.get('passphrase')
                            or _get_system_setting_value('backup_encryption_passphrase', '')
                            or ''
                        )
                        if not passphrase:
                            return jsonify({
                                'error': 'Encrypted backup requires its passphrase for verification'
                            }), 400

                        with tempfile.NamedTemporaryFile(
                            prefix='gnss-caster-verify-', suffix='.tar.gz', delete=False
                        ) as temp_plain:
                            temp_plain_path = temp_plain.name

                        decrypt_env = os.environ.copy()
                        decrypt_env['PASSPHRASE'] = passphrase
                        decrypt_result = subprocess.run(
                            [
                                'openssl', 'enc', '-d', '-aes-256-cbc', '-pbkdf2',
                                '-iter', '200000', '-in', archive_path,
                                '-out', temp_plain_path, '-pass', 'env:PASSPHRASE'
                            ],
                            capture_output=True, text=True, timeout=120,
                            env=decrypt_env,
                        )
                        if decrypt_result.returncode != 0:
                            return jsonify({
                                'error': 'Encrypted backup could not be decrypted with the supplied/current passphrase'
                            }), 400
                        verify_path = temp_plain_path

                    result = subprocess.run(
                        ['tar', '-tzf', verify_path],
                        capture_output=True, text=True, timeout=120,
                    )
                    if result.returncode == 0:
                        entry_count = len([line for line in result.stdout.splitlines() if line.strip()])
                        return jsonify({
                            'success': True,
                            'message': f'Archive is readable ({entry_count} entries)',
                        })
                    return jsonify({
                        'error': 'Archive is unreadable: ' + (result.stderr or '').strip()[:200]
                    }), 400
                finally:
                    if temp_plain_path:
                        try:
                            os.unlink(temp_plain_path)
                        except OSError:
                            pass
            except subprocess.TimeoutExpired:
                return jsonify({'error': 'Verification timed out'}), 504
            except Exception as e:
                return jsonify({'error': str(e)}), 500

