            try:
                upload = request.files.get('file')
                if upload is None:
                    return jsonify({'error': 'Choose a backup file'}), 400
                stored = _store_uploaded_backup(upload, app.config.get('BACKUP_UPLOAD_DIR', '/opt/gnss-caster/backups'))
                return jsonify({**stored, 'message': 'File uploaded. Confirm restoration to continue. The archive contents will be checked before the service is stopped.'}), 201
            except ValueError as error:
                return jsonify({'error': str(error)}), 400
            except OSError:
                logger.exception('Could not store uploaded backup')
                return jsonify({'error': 'Could not save the backup. Check available disk space.'}), 500

