        @app.route('/api/site_points/save', methods=['POST'])
        @login_required
        def api_site_point_save():
            """Create or update a point. Named points are matched by name."""
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                from app.db.models import SitePoint

                data = request.get_json(silent=True) or {}
                name = str(data.get('name', '')).strip()
                if not name or len(name) > 120:
                    return jsonify({'error': 'A point name of 1-120 characters is required'}), 400

                try:
                    latitude = float(data.get('latitude'))
                    longitude = float(data.get('longitude'))
                except (TypeError, ValueError):
                    return jsonify({'error': 'Latitude and longitude must be numbers'}), 400

                if not (-90 <= latitude <= 90) or not (-180 <= longitude <= 180):
                    return jsonify({'error': 'Coordinates are out of range'}), 400

                point = SitePoint.query.filter_by(name=name).first()
                if point is None:
                    point = SitePoint(name=name)
                    db.session.add(point)

                point.description = str(data.get('description', ''))[:255]
                point.latitude = latitude
                point.longitude = longitude
                point.altitude = _to_float_or_default(data.get('altitude', 0), 0.0)
                point.antenna_height = _to_float_or_default(data.get('antenna_height', 0), 0.0)
                point.add_antenna_height = bool(data.get('add_antenna_height', False))
                point.updated_at = int(time.time())
                db.session.commit()

                return jsonify({'success': True, 'id': point.id, 'message': f'Point "{name}" saved'})
            except Exception as e:
                db.session.rollback()
                logger.error(f'Error saving site point: {e}')
                return jsonify({'error': str(e)}), 500

