        @app.route('/api/system/settings/update', methods=['POST'])
        @login_required
        def api_update_system_settings():
            try:
                role_error = _require_admin_role()
                if role_error:
                    return role_error

                data = request.json or {}
                if not data:
                    return jsonify({'error': 'No data provided'}), 400

                validated_values = {}

                for key, value in data.items():
                    normalized_key = str(key or '').strip()
                    if not normalized_key:
                        continue

                    if normalized_key in ('system_name', 'bluetooth_name'):
                        normalized_value = str(value or '').strip()
                        if not normalized_value:
                            return jsonify({'error': f'{normalized_key} cannot be empty'}), 400
                        if len(normalized_value) > 64:
                            return jsonify({'error': f'{normalized_key} must be 64 characters or less'}), 400
                    elif normalized_key == 'max_connections':
                        normalized_value = int(value)
                        if normalized_value < 1 or normalized_value > 1000:
                            return jsonify({'error': 'max_connections must be between 1 and 1000'}), 400
                    elif normalized_key == 'log_retention':
                        normalized_value = int(value)
                        if normalized_value < 1 or normalized_value > 365:
                            return jsonify({'error': 'log_retention must be between 1 and 365'}), 400
                    elif normalized_key == 'data_retention':
                        normalized_value = int(value)
                        if normalized_value < 1 or normalized_value > 3650:
                            return jsonify({'error': 'data_retention must be between 1 and 3650'}), 400
                    elif normalized_key == 'telegram_language':
                        normalized_value = str(value or '').strip().lower()
                        if normalized_value not in ('en', 'ru'):
                            return jsonify({'error': 'Telegram language must be en or ru'}), 400
                    elif normalized_key == 'telegram_bot_token':
                        normalized_value = str(value or '').strip()
                        if normalized_value and not re.fullmatch(r'\d{5,}:[A-Za-z0-9_-]{20,}', normalized_value):
                            return jsonify({'error': 'telegram_bot_token should look like 123456789:AA... (from @BotFather)'}), 400
                    elif normalized_key == 'backup_encryption_passphrase':
                        normalized_value = str(value or '')
                        if normalized_value and len(normalized_value) < 12:
                            return jsonify({'error': 'backup_encryption_passphrase must be at least 12 characters'}), 400
                    elif normalized_key == 'telegram_admin_id':
                        normalized_value = str(value or '').strip()
                        if normalized_value and not re.fullmatch(r'-?\d{1,32}', normalized_value):
                            return jsonify({'error': 'telegram_admin_id must be a numeric chat ID'}), 400
                    elif normalized_key == 'telegram_chat_id':
                        normalized_value = str(value or '').strip()
                        if normalized_value and not re.fullmatch(r'-?\d{1,32}|@[A-Za-z0-9_]{4,64}', normalized_value):
                            return jsonify({'error': 'telegram_chat_id must be a numeric ID or an @channelname'}), 400
                    elif normalized_key == 'backup_external_path':
                        # Free-form path from the operator: it ends up in a
                        # shell script, so keep it strict - absolute, no shell
                        # metacharacters, no traversal. Empty disables the copy.
                        normalized_value = str(value or '').strip()
                        if normalized_value:
                            if not normalized_value.startswith('/'):
                                return jsonify({'error': 'backup_external_path must be an absolute path'}), 400
                            if '..' in normalized_value:
                                return jsonify({'error': 'backup_external_path must not contain ".."'}), 400
                            if not re.fullmatch(r'[A-Za-z0-9 ._/-]{1,255}', normalized_value):
                                return jsonify({'error': 'backup_external_path may only contain letters, digits, spaces, dots, dashes, underscores and slashes'}), 400
                    elif normalized_key == 'backup_interval':
                        normalized_value = int(value)
                        if normalized_value < 3600 or normalized_value > 604800:
                            return jsonify({'error': 'backup_interval must be between 3600 and 604800 seconds'}), 400
                    elif normalized_key in (
                        'auto_backup',
                        'ntrip_enabled',
                        'bluetooth_enabled',
                        'bluetooth_discoverable',
                    ):
                        normalized_value = str(value).strip().lower() in ('1', 'true', 'yes', 'on')
                    else:
                        normalized_value = value

                    validated_values[normalized_key] = normalized_value

                warnings = []
                applied = {}
                # Track which settings actually changed value. Warnings must be
                # driven by this, not by mere presence in the request: the UI
                # always submits the whole form, so keying off presence made
                # every save report every possible restart warning.
                changed_keys = set()

                for key, value in validated_values.items():
                    stored_value = value
                    if isinstance(value, bool):
                        stored_value = 'true' if value else 'false'

                    setting = SystemSetting.query.filter_by(key=key).first()

                    if setting:
                        if str(setting.value) != str(stored_value):
                            changed_keys.add(key)
                        setting.value = str(stored_value)
                        setting.updated_at = int(time.time())
                    else:
                        changed_keys.add(key)
                        setting = SystemSetting(
                            key=key,
                            value=str(stored_value),
                            description=''
                        )
                        db.session.add(setting)

                db.session.commit()

                effective_bluetooth_enabled = str(
                    _get_system_setting_value('bluetooth_enabled', 'true')
                ).strip().lower() in ('1', 'true', 'yes', 'on')

                alias_to_apply = ''
                if 'bluetooth_name' in changed_keys:
                    alias_to_apply = str(validated_values.get('bluetooth_name', '')).strip()
                    if not alias_to_apply:
                        alias_to_apply = str(validated_values.get('system_name', '')).strip()
                elif 'system_name' in changed_keys:
                    alias_to_apply = str(validated_values.get('system_name', '')).strip()

                if alias_to_apply and effective_bluetooth_enabled:
                    warning_text = 'Bluetooth name change is saved and will apply after service restart'
                    warnings.append(warning_text)
                    applied['bluetooth_name'] = 'saved; will apply after service restart'
                elif alias_to_apply:
                    applied['bluetooth_name'] = 'saved; Bluetooth manager is disabled'

                if 'bluetooth_discoverable' in changed_keys:
                    discoverable_enabled = bool(validated_values.get('bluetooth_discoverable'))
                    if effective_bluetooth_enabled:
                        warning_text = (
                            'Bluetooth discoverable change is saved and will apply after service restart'
                        )
                        warnings.append(warning_text)
                        applied['bluetooth_discoverable'] = 'saved; will apply after service restart'
                    else:
                        applied['bluetooth_discoverable'] = 'saved; Bluetooth manager is disabled'

                # Privileged side-effects (logrotate/backup cron) call sudo
                # helpers and can exceed nginx's proxy_read_timeout under load,
                # causing the connection to be reset and the browser to show
                # "Failed to fetch". Run them off the request thread so the
                # response returns immediately, and record job status so the
                # UI can poll /api/system/jobs/<id> for the real outcome (Fix #14).
                def _register_job(kind):
                    job_id = uuid.uuid4().hex[:12]
                    with _system_jobs_lock:
                        _system_jobs[job_id] = {
                            'id': job_id,
                            'kind': kind,
                            'status': 'running',
                            'started_at': int(time.time()),
                            'finished_at': None,
                            'error': None,
                        }
                    return job_id

                def _finish_job(job_id, error=None):
                    with _system_jobs_lock:
                        job = _system_jobs.get(job_id)
                        if job:
                            job['status'] = 'error' if error else 'done'
                            job['finished_at'] = int(time.time())
                            job['error'] = str(error) if error else None
                        # Trim old jobs (keep last 50)
                        if len(_system_jobs) > 50:
                            for stale_id in sorted(
                                _system_jobs,
                                key=lambda k: _system_jobs[k]['started_at']
                            )[:len(_system_jobs) - 50]:
                                _system_jobs.pop(stale_id, None)

                def _apply_logrotate_async(rotation_days, job_id):
                    try:
                        _write_logrotate_config(rotation_days)
                        _finish_job(job_id)
                    except Exception as logrotate_error:
                        logger.warning(
                            f"Async logrotate update failed: {logrotate_error}"
                        )
                        _finish_job(job_id, error=logrotate_error)

                def _apply_backup_cron_async(enabled, interval, job_id):
                    try:
                        _write_backup_cron(enabled, interval)
                        _finish_job(job_id)
                    except Exception as backup_cron_error:
                        logger.warning(
                            f"Async backup cron update failed: {backup_cron_error}"
                        )
                        _finish_job(job_id, error=backup_cron_error)

                if 'log_retention' in validated_values:
                    job_id = _register_job('logrotate')
                    threading.Thread(
                        target=_apply_logrotate_async,
                        args=(validated_values.get('log_retention'), job_id),
                        daemon=True,
                        name='gnss-caster-logrotate-apply'
                    ).start()
                    applied['logrotate_path'] = 'scheduled'
                    applied['logrotate_job_id'] = job_id

                if 'auto_backup' in validated_values or 'backup_interval' in validated_values:
                    auto_backup_enabled = bool(
                        validated_values.get(
                            'auto_backup',
                            str(_get_system_setting_value('auto_backup', 'true')).strip().lower() in ('1', 'true', 'yes', 'on')
                        )
                    )
                    backup_interval = int(
                        validated_values.get(
                            'backup_interval',
                            int(_get_system_setting_value('backup_interval', '86400') or 86400)
                        )
                    )
                    job_id = _register_job('backup_cron')
                    threading.Thread(
                        target=_apply_backup_cron_async,
                        args=(auto_backup_enabled, backup_interval, job_id),
                        daemon=True,
                        name='gnss-caster-backupcron-apply'
                    ).start()
                    applied['backup_cron'] = 'scheduled'
                    applied['backup_cron_job_id'] = job_id

                if 'bluetooth_enabled' in changed_keys:
                    bluetooth_enabled = bool(validated_values.get('bluetooth_enabled'))
                    applied['bluetooth_enabled'] = (
                        'saved as enabled; apply after service restart'
                        if bluetooth_enabled else
                        'saved as disabled; apply after service restart'
                    )
                    warnings.append('Bluetooth enable/disable change will apply after service restart')

                if 'ntrip_enabled' in changed_keys or 'max_connections' in changed_keys:
                    ntrip_enabled = str(
                        _get_system_setting_value('ntrip_enabled', 'true')
                    ).strip().lower() in ('1', 'true', 'yes', 'on')
                    applied['ntrip_enabled'] = (
                        'saved as enabled; apply after service restart'
                        if ntrip_enabled else
                        'saved as disabled; apply after service restart'
                    )
                    if 'max_connections' in changed_keys:
                        applied['max_connections'] = int(validated_values.get('max_connections'))
                    warnings.append('NTRIP enable/disable and max connection changes will apply after service restart')

                return jsonify({
                    'message': 'System settings updated',
                    'warnings': warnings,
                    'applied': applied,
                }), 200
            except ValueError as e:
                db.session.rollback()
                logger.error(f"Validation error updating system settings: {e}")
                return jsonify({'error': str(e)}), 400
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error updating system settings: {e}")
                return jsonify({'error': str(e)}), 500

